theorem RepresentsPreference.lt_iff [Preorder α] [Preorder β] {u : α → β}
    (h : RepresentsPreference u) (a b : α) :
    a < b ↔ u a < u b

theorem RepresentsPreference.indifferent_iff [Preorder α] [Preorder β] {u : α → β}
    (h : RepresentsPreference u) (a b : α) :
    Indifferent a b ↔ Indifferent (u a) (u b)
